#include <iostream>
#include <utility>
#include <vector>

#include <cbmpc/internal/crypto/base_ecc_secp256k1.h>
#include <cbmpc/internal/crypto/ro.h>
#include <cbmpc/internal/protocol/schnorr_mp.h>
#include <cbmpc/internal/protocol/util.h>
#include <cbmpc/internal/zk/zk_elgamal_com.h>
#include <cbmpc/internal/zk/zk_pedersen.h>

#define _i msg
#define _j received(j)
#define _js all_received()

using namespace coinbase::mpc;

namespace coinbase::mpc::schnorrmp {

error_t dkg(job_mp_t& job, ecurve_t curve, key_t& key, buf_t& sid) {
  return eckey::key_share_mp_t::dkg(job, curve, key, sid);
}

error_t refresh(job_mp_t& job, buf_t& sid, key_t& key, key_t& new_key) {
  return eckey::key_share_mp_t::refresh(job, sid, key, new_key);
}

error_t dkg_ac(job_mp_t& job, ecurve_t curve, buf_t& sid, const crypto::ss::ac_t ac,
               const party_set_t& quorum_party_set, key_t& key) {
  return eckey::key_share_mp_t::dkg_ac(job, curve, sid, ac, quorum_party_set, key);
}

error_t refresh_ac(job_mp_t& job, ecurve_t curve, buf_t& sid, const crypto::ss::ac_t ac,
                   const party_set_t& quorum_party_set, key_t& key, key_t& new_key) {
  return eckey::key_share_mp_t::refresh_ac(job, curve, sid, ac, quorum_party_set, key, new_key);
}

static bn_t calc_eddsa_HRAM(const ecc_point_t& R, const ecc_point_t& Q, mem_t in) {
  buf_t HRAM_buf = crypto::sha512_t::hash(R, Q.to_compressed_bin(), in);
  bn_t HRAM = bn_t::from_bin(HRAM_buf.rev()) % crypto::curve_ed25519.order();
  return HRAM;
}

error_t sign(job_mp_t& job, key_t& key, const mem_t& msg, party_idx_t sig_receiver, buf_t& sig, variant_e variant) {
  sig.free();
  error_t rv = UNINITIALIZED_ERROR;
  std::vector<mem_t> msgs(1, msg);
  std::vector<buf_t> sigs;
  if (rv = sign_batch(job, key, msgs, sig_receiver, sigs, variant)) return rv;
  sig = sigs[0];
  return SUCCESS;
}

error_t sign_batch(job_mp_t& job, key_t& key, const std::vector<mem_t>& msgs, party_idx_t sig_receiver,
                   std::vector<buf_t>& sigs, variant_e variant) {
  sigs.clear();
  error_t rv = UNINITIALIZED_ERROR;

  int n = job.get_n_parties();
  int i = job.get_party_idx();
  crypto::pname_t pname = job.get_name();

  ecurve_t curve = key.curve;
  const mod_t& q = curve.order();
  const auto& G = curve.generator();

  if (key.party_name != pname) return coinbase::error(E_BADARG, "Wrong role");
  if (key.Qis.size() != n) return coinbase::error(E_BADARG, "Wrong number of peers");
  if (key.x_share * G != key.Qis.at(pname)) return coinbase::error(E_BADARG, "x_share does not match Qi");
  if (SUM(key.Qis) != key.Q) return coinbase::error(E_BADARG, "Q does not match the sum of Qis");
  auto h_consistency = job.uniform_msg<buf256_t>();
  h_consistency._i = crypto::sha256_t::hash(msgs, key.Q, key.Qis);

  auto sid_i = job.uniform_msg<buf_t>(crypto::gen_random_bitlen(SEC_P_COM));
  auto ki = job.uniform_msg<std::vector<bn_t>>(std::vector<bn_t>(msgs.size()));
  auto Ri = job.uniform_msg<std::vector<ecc_point_t>>(std::vector<ecc_point_t>(msgs.size()));
  for (size_t l = 0; l < msgs.size(); l++) {
    ki[l] = bn_t::rand(q);
    Ri[l] = ki[l] * G;
  }

  coinbase::crypto::commitment_t com(sid_i, job.get_pid(i));
  com.gen(Ri._i);
  auto c = job.uniform_msg<buf_t>(com.msg);
  auto rho = job.uniform_msg<buf256_t>(com.rand);

  if (rv = job.plain_broadcast(c, sid_i, h_consistency)) return rv;

  for (int j = 0; j < n; j++) {
    if (j == i) continue;
    if (h_consistency._j != h_consistency) return coinbase::error(E_CRYPTO);
  }
  auto sid = job.uniform_msg<buf_t>();
  sid._i = crypto::sha256_t::hash(sid_i._js);

  auto h = job.uniform_msg<buf256_t>();
  h._i = crypto::sha256_t::hash(c._js);
  auto pi = job.uniform_msg<zk::uc_batch_dl_t>();
  pi.prove(Ri, ki, sid, i);
  if (rv = job.plain_broadcast(sid, h, Ri, rho, pi)) return rv;

  for (int j = 0; j < n; j++) {
    if (job.is_party_idx(j)) continue;

    if (sid._j != sid._i) return coinbase::error(E_CRYPTO);
    if (h._j != h._i) return coinbase::error(E_CRYPTO);
    if (Ri._j.size() != msgs.size())
      return coinbase::error(E_CRYPTO, "schnorrmp::sign_batch: inconsistent batch size (Ri)");
    for (const auto& point : Ri._j) {
      if (rv = curve.check(point)) return coinbase::error(rv, "schnorr_mp_t::sign_batch: check Ri failed");
    }
    if (rv = pi._j.verify(Ri._j, sid._i, j)) return coinbase::error(rv, "schnorr_mp_t::sign_batch: verify pi failed");

    if (rv = coinbase::crypto::commitment_t(sid_i._j, job.get_pid(j)).set(rho._j, c._j).open(Ri._j)) return rv;
  }

  std::vector<ecc_point_t> R(msgs.size());
  for (size_t l = 0; l < msgs.size(); l++) {
    R[l] = Ri._i[l];
    for (int j = 0; j < n; j++) {
      if (j == i) continue;
      R[l] += Ri._j[l];
    }
  }

  std::vector<bn_t> e(msgs.size());

  if (variant == variant_e::EdDSA) {
    if (key.curve != crypto::curve_ed25519) return coinbase::error(E_BADARG, "EdDSA variant requires EdDSA curve");
    for (size_t l = 0; l < msgs.size(); l++) {
      e[l] = calc_eddsa_HRAM(R[l], key.Q, msgs[l]);
    }
  } else if (variant == variant_e::BIP340) {
    if (key.curve != crypto::curve_secp256k1)
      return coinbase::error(E_BADARG, "BIP340 variant requires secp256k1 curve");
    bn_t rx, ry;
    for (size_t l = 0; l < msgs.size(); l++) {
      if (msgs[l].size != 32) return coinbase::error(E_BADARG, "schnorr_mp: BIP340 msg size != 32");
      if (!msgs[l].data) return coinbase::error(E_BADARG, "schnorr_mp: BIP340 msg is null");
      R[l].get_coordinates(rx, ry);
      if (ry.is_odd()) ki[l] = q - ki[l];
      e[l] = crypto::bip340::hash_message(rx, key.Q, msgs[l]);
      if (key.Q.get_y().is_odd()) e[l] = q - e[l];
    }
  } else {
    cb_assert(false && "schnorr_mp: non-existing variant");
  }

  auto ssi = job.uniform_msg<std::vector<bn_t>>();
  ssi.msg.resize(msgs.size());
  for (size_t l = 0; l < msgs.size(); l++) {
    ssi.msg[l] = (e[l] * key.x_share + ki[l]) % q;
  }

  if (rv = job.send_message_all_to_one(sig_receiver, ssi)) return rv;

  std::vector<buf_t> candidate_sigs(msgs.size());
  if (job.is_party_idx(sig_receiver)) {
    std::vector<bn_t> ss(msgs.size(), 0);
    for (int j = 0; j < n; j++) {
      if (ssi._j.size() != msgs.size())
        return coinbase::error(E_CRYPTO, "schnorrmp::sign_batch: inconsistent batch size (ssi)");
      for (size_t l = 0; l < msgs.size(); l++) MODULO(q) ss[l] += ssi._j[l];
    }

    crypto::ecc_pub_key_t verify_key(key.Q);
    if (key.curve == crypto::curve_ed25519) {
      for (size_t l = 0; l < msgs.size(); l++) {
        candidate_sigs[l] = R[l].to_compressed_bin() + ss[l].to_bin(crypto::ed25519::prv_bin_size()).rev();
        if (rv = verify_key.verify(msgs[l], candidate_sigs[l])) return coinbase::error(rv, "ed25519 verify failed");
      }
    } else if (key.curve == crypto::curve_secp256k1) {
      bn_t rx, ry;
      for (size_t l = 0; l < msgs.size(); l++) {
        R[l].get_coordinates(rx, ry);
        candidate_sigs[l] = rx.to_bin(32) + ss[l].to_bin(32);
        if (rv = crypto::bip340::verify(verify_key, msgs[l], candidate_sigs[l])) {
          return coinbase::error(rv, "bip340 verify failed");
        }
      }
    } else {
      cb_assert(false && "schnorr_mp: non-existing variant");
    }
  }
  sigs = std::move(candidate_sigs);
  return SUCCESS;
}

}  // namespace coinbase::mpc::schnorrmp


// ==========================================
// FULL FILE: https://raw.githubusercontent.com/coinbase/cb-mpc/master/src/cbmpc/protocol/pve_ac.cpp
// ==========================================
#include <cbmpc/internal/protocol/pve_ac.h>

using namespace coinbase::crypto;

namespace coinbase::mpc {

static const int pve_ac_seed_size = coinbase::bits_to_bytes(SEC_P_COM);
static const int pve_ac_seed_pair_size = 2 * pve_ac_seed_size;

static buf_t batch_to_bin(ecurve_t curve, const std::vector<bn_t>& x) {
  int batch_size = int(x.size());
  int curve_size = curve.size();
  buf_t bin(batch_size * curve_size);
  for (int j = 0; j < batch_size; j++) x[j].to_bin(bin.range(j * curve_size, curve_size));
  return bin;
}

static error_t batch_from_bin(ecurve_t curve, int batch_size, mem_t bin, std::vector<bn_t>& x) {
  int curve_size = curve.size();
  if (bin.size != batch_size * curve_size) return coinbase::error(E_CRYPTO);
  x.resize(batch_size);
  for (int j = 0; j < batch_size; j++) x[j] = bn_t::from_bin(bin.range(j * curve_size, curve_size));
  return SUCCESS;
}

error_t ec_pve_ac_t::encrypt_row(const pve_base_pke_i& base_pke, const ss::ac_t& ac, const pks_t& ac_pks, mem_t L,
                                 ecurve_t curve, mem_t seed, mem_t plain, buf_t& c,
                                 std::vector<ciphertext_adapter_t>& quorum_c) const {
  error_t rv = UNINITIALIZED_ERROR;
  if (seed.size != pve_ac_seed_size) return coinbase::error(E_CRYPTO);
  const mod_t& q = curve.order();
  crypto::drbg_aes_ctr_t drbg(seed);
  bn_t K = drbg.gen_bn(q);

  std::map<std::string, bn_t> K_shares = ac.share(curve.order(), K, &drbg);
  for (const auto& [path, pub_key_ptr] : ac_pks) {
    ciphertext_adapter_t item;
    buf_t ct_ser;
    if (rv = base_pke.encrypt(pub_key_ptr, L, K_shares[path].to_bin(), drbg.gen(32), ct_ser)) return rv;
    item.ct_ser = ct_ser;
    quorum_c.push_back(std::move(item));
  }

  buf_t k_and_iv = crypto::ro::hash_string(K, L).bitlen(256 + iv_bitlen);
  mem_t k_aes = k_and_iv.take(32);
  mem_t iv = k_and_iv.skip(32);

  crypto::aes_gcm_t::encrypt(k_aes, iv, L, tag_size, plain, c);
  return SUCCESS;
}

error_t ec_pve_ac_t::encrypt_row0(const pve_base_pke_i& base_pke, const ss::ac_t& ac, const pks_t& ac_pks, mem_t L,
                                  ecurve_t curve, mem_t r0_1, mem_t r0_2, int batch_size, std::vector<bn_t>& x0,
                                  buf_t& c0, std::vector<ciphertext_adapter_t>& quorum_c0) const {
  if (r0_1.size != pve_ac_seed_size) return coinbase::error(E_CRYPTO);
  const mod_t& q = curve.order();
  x0.resize(batch_size);
  crypto::drbg_aes_ctr_t drbg(r0_1);
  for (int j = 0; j < batch_size; j++) x0[j] = drbg.gen_bn(q);
  return encrypt_row(base_pke, ac, ac_pks, L, curve,
                     r0_2,      // seed
                     r0_1,      // plain
                     c0,        // output
                     quorum_c0  // output
  );
}

error_t ec_pve_ac_t::encrypt_row1(const pve_base_pke_i& base_pke, const ss::ac_t& ac, const pks_t& ac_pks, mem_t L,
                                  ecurve_t curve, mem_t r1, mem_t x1_bin, buf_t& c1,
                                  std::vector<ciphertext_adapter_t>& quorum_c1) const {
  return encrypt_row(base_pke, ac, ac_pks, L, curve,
                     r1,        // seed
                     x1_bin,    // plain
                     c1,        // output
                     quorum_c1  // output
  );
}

error_t ec_pve_ac_t::encrypt(const pve_base_pke_i& base_pke, const ss::ac_t& ac, const pks_t& ac_pks, mem_t label,
                             ecurve_t curve, const std::vector<bn_t>& _x) {
  error_t rv = UNINITIALIZED_ERROR;
  int batch_size = int(_x.size());
  const auto& G = curve.generator();
  const mod_t& q = curve.order();

  std::vector<bn_t> x(batch_size);
  Q.resize(batch_size);
  for (int i = 0; i < batch_size; i++) {
    x[i] = _x[i] % q;
    Q[i] = x[i] * G;
  }
  L = crypto::sha256_t::hash(label, Q);

  std::vector<std::vector<ecc_point_t>> X0(kappa);
  std::vector<std::vector<ecc_point_t>> X1(kappa);
  std::vector<buf_t> c0(kappa);
  std::vector<buf_t> c1(kappa);
  std::vector<std::vector<ciphertext_adapter_t>> quorum_c0(kappa);
  std::vector<std::vector<ciphertext_adapter_t>> quorum_c1(kappa);
  std::vector<buf_t> r0_1(kappa);
  std::vector<buf_t> r0_2(kappa);
  std::vector<buf_t> r1(kappa);

  for (int i = 0; i < kappa; i++) {
    X0[i].resize(batch_size);
    X1[i].resize(batch_size);

    r0_1[i] = crypto::gen_random_bitlen(SEC_P_COM);
    r0_2[i] = crypto::gen_random_bitlen(SEC_P_COM);
    r1[i] = crypto::gen_random_bitlen(SEC_P_COM);

    std::vector<bn_t> x0;
    if (rv = encrypt_row0(base_pke, ac, ac_pks, L, curve, r0_1[i], r0_2[i], batch_size, x0, c0[i], quorum_c0[i]))
      return rv;

    std::vector<bn_t> x1(batch_size);
    for (int j = 0; j < batch_size; j++) MODULO(q) x1[j] = x[j] - x0[j];

    row_t& row = rows[i];
    row.x_bin = batch_to_bin(curve, x1);
    if (rv = encrypt_row1(base_pke, ac, ac_pks, L, curve, r1[i], row.x_bin, c1[i], quorum_c1[i])) return rv;

    for (int j = 0; j < batch_size; j++) {
      X0[i][j] = x0[j] * G;
      X1[i][j] = Q[j] - X0[i][j];
    }
  }

  b = crypto::ro::hash_string(Q, label, c0, c1, quorum_c0, quorum_c1, X0, X1).bitlen(kappa);

  for (int i = 0; i < kappa; i++) {
    bool bit = b.get_bit(i);
    rows[i].r = bit ? r1[i] : (r0_1[i] + r0_2[i]);  // concat
    rows[i].c = bit ? c0[i] : c1[i];
    rows[i].quorum_c = bit ? quorum_c0[i] : quorum_c1[i];
    if (!bit) rows[i].x_bin.free();  // clear output
  }
  return SUCCESS;
}

error_t ec_pve_ac_t::verify(const pve_base_pke_i& base_pke, const ss::ac_t& ac, const pks_t& ac_pks,
                            const std::vector<ecc_point_t>& Q, mem_t label) const {
  error_t rv = UNINITIALIZED_ERROR;
  int batch_size = int(Q.size());
  if (batch_size == 0) return coinbase::error(E_BADARG);

  ecurve_t curve = Q[0].get_curve();
  const auto& G = curve.generator();
  if (Q.size() != this->Q.size()) return coinbase::error(E_CRYPTO);
  for (int i = 0; i < batch_size; i++) {
    if (rv = curve.check(Q[i])) return coinbase::error(rv, "ec_pve_ac_t::verify: check Q[i] failed");
  }
  if (Q != this->Q) return coinbase::error(E_CRYPTO);

  buf_t L = crypto::sha256_t::hash(label, Q);
  if (L != this->L) return coinbase::error(E_CRYPTO);

  std::vector<std::vector<ecc_point_t>> X0(kappa);
  std::vector<std::vector<ecc_point_t>> X1(kappa);
  std::vector<buf_t> c0(kappa);
  std::vector<buf_t> c1(kappa);
  std::vector<std::vector<ciphertext_adapter_t>> quorum_c0(kappa);
  std::vector<std::vector<ciphertext_adapter_t>> quorum_c1(kappa);

  for (int i = 0; i < kappa; i++) {
    X0[i].resize(batch_size);
    X1[i].resize(batch_size);
    bool bit = b.get_bit(i);
    const row_t& row = rows[i];

    std::vector<bn_t> xb;
    if (bit) {
      c0[i] = row.c;
      quorum_c0[i] = row.quorum_c;
      if (rv = batch_from_bin(curve, batch_size, row.x_bin, xb)) return rv;
      mem_t r1 = row.r;
      if (rv = encrypt_row1(base_pke, ac, ac_pks, L, curve, r1, row.x_bin, c1[i], quorum_c1[i])) return rv;
    } else {
      c1[i] = row.c;
      quorum_c1[i] = row.quorum_c;
      if (row.r.size() != pve_ac_seed_pair_size) return coinbase::error(E_CRYPTO);
      mem_t r0_1 = row.r.take(pve_ac_seed_size);
      mem_t r0_2 = row.r.skip(pve_ac_seed_size);
      if (rv = encrypt_row0(base_pke, ac, ac_pks, L, curve, r0_1, r0_2, batch_size, xb, c0[i], quorum_c0[i])) return rv;
    }

    for (int j = 0; j < batch_size; j++) {
      ecc_point_t Xb = xb[j] * G;
      X1[i][j] = bit ? Xb : Q[j] - Xb;
      X0[i][j] = bit ? Q[j] - Xb : Xb;
    }
  }

  buf128_t b_tag;
  b_tag = crypto::ro::hash_string(Q, label, c0, c1, quorum_c0, quorum_c1, X0, X1).bitlen(SEC_P_COM);
  if (b_tag != b) return coinbase::error(E_CRYPTO);
  return SUCCESS;
}

error_t ec_pve_ac_t::find_quorum_ciphertext(const std::vector<std::string>& sorted_leaves, const std::string& path,
                                            const row_t& row, const ciphertext_adapter_t*& c) {
  auto it = std::find(sorted_leaves.begin(), sorted_leaves.end(), path);
  if (it == sorted_leaves.end()) return coinbase::error(E_NOT_FOUND, "path not found");
  auto index = it - sorted_leaves.begin();

  const auto& quorum_c = row.quorum_c;
  if (index >= quorum_c.size()) return coinbase::error(E_NOT_FOUND, "path not found");
  c = &quorum_c[index];

  return SUCCESS;
}

error_t ec_pve_ac_t::party_decrypt_row(const pve_base_pke_i& base_pke, const ss::ac_t& ac, int row_index,
                                       const std::string& path, pve_keyref_t prv_key, mem_t label,
                                       bn_t& out_share) const {
  error_t rv = UNINITIALIZED_ERROR;
  if (row_index < 0 || row_index >= kappa) return coinbase::error(E_RANGE);
  if (Q.empty()) return coinbase::error(E_BADARG);

  const row_t& row = rows[row_index];

  buf_t L = crypto::sha256_t::hash(label, Q);

  std::set<std::string> leaves = ac.list_leaf_names();
  std::vector<std::string> sorted_leaves(leaves.begin(), leaves.end());

  const ciphertext_adapter_t* c;
  if (rv = find_quorum_ciphertext(sorted_leaves, path, row, c)) return rv;

  buf_t plain;
  if (rv = base_pke.decrypt(prv_key, L, c->ct_ser, plain)) return rv;
  if (plain.size() > Q[0].get_curve().order().get_bin_size()) return coinbase::error(E_CRYPTO);
  out_share = bn_t::from_bin(plain);
  return SUCCESS;
}

error_t ec_pve_ac_t::aggregate_to_restore_row(const pve_base_pke_i& base_pke, const ss::ac_t& ac, int row_index,
                                              mem_t label, const std::map<std::string, bn_t>& quorum_decrypted,
                                              std::vector<bn_t>& x, bool skip_verify, const pks_t& all_ac_pks) const {
  error_t rv = UNINITIALIZED_ERROR;
  if (row_index < 0 || row_index >= kappa) return coinbase::error(E_RANGE);
  if (Q.empty()) return coinbase::error(E_BADARG);

  if (!skip_verify) {
    if (all_ac_pks.empty()) {
      return coinbase::error(E_BADARG, "all_ac_pks is required when skip_verify is false");
    }
    if (rv = verify(base_pke, ac, all_ac_pks, Q, label)) return rv;
  }

  const row_t& row = rows[row_index];

  int batch_size = int(Q.size());
  ecurve_t curve = Q[0].get_curve();
  int curve_size = curve.size();
  const auto& G = curve.generator();
  const mod_t& q = curve.order();

  buf_t L = crypto::sha256_t::hash(label, Q);

  bn_t K;
  if (rv = ac.reconstruct(q, quorum_decrypted, K)) return rv;

  buf_t k_and_iv = crypto::ro::hash_string(K, L).bitlen(256 + iv_bitlen);
  mem_t k_aes = k_and_iv.take(32);
  mem_t iv = k_and_iv.skip(32);

  buf_t decrypted_data;
  if (rv = crypto::aes_gcm_t::decrypt(k_aes, iv, L, tag_size, row.c, decrypted_data)) return rv;

  mem_t seed;
  mem_t x_bin;

  bool bit = b.get_bit(row_index);
  if (bit) {
    x_bin = row.x_bin;
    seed = decrypted_data;
  } else {
    x_bin = decrypted_data;
    if (row.r.size() != pve_ac_seed_pair_size) return coinbase::error(E_CRYPTO);
    seed = row.r.take(pve_ac_seed_size);
  }

  if (x_bin.size != batch_size * curve_size) return coinbase::error(E_CRYPTO);
  if (seed.size != pve_ac_seed_size) return coinbase::error(E_CRYPTO);
  crypto::drbg_aes_ctr_t drbg(seed);
  x.resize(batch_size);
  for (int j = 0; j < batch_size; j++) {
    bn_t x0 = drbg.gen_bn(q);
    bn_t x1 = bn_t::from_bin(x_bin.range(j * curve_size, curve_size));
    MODULO(q) x[j] = x0 + x1;
    if (x[j] * G != Q[j]) return coinbase::error(E_CRYPTO);
  }

  return SUCCESS;
}

}  // namespace coinbase::mpc


